// plugins/withGradleMemory.js
//
// Expo SDK 54 builds (React Native 0.81, KSP and Android lint over many native modules) need more
// Gradle JVM memory than the template's generated default (-Xmx2048m, 512 MB Metaspace). With the
// default, release builds fail with "java.lang.OutOfMemoryError: Metaspace" in KSP and in the lint
// vital tasks. EAS cloud builds use the same generated gradle.properties, so a hand edit of the
// local android/ folder would not protect them.
//
// android/ is gitignored and regenerated by `expo prebuild`; this plugin makes the setting durable.
const { withGradleProperties } = require('@expo/config-plugins');

const KEY = 'org.gradle.jvmargs';
const VALUE = '-Xmx4096m -XX:MaxMetaspaceSize=1024m';

/** Sets the Gradle JVM arguments in a parsed gradle.properties list, replacing any existing entry. */
function setGradleJvmArgs(properties) {
  const existing = properties.find((item) => item.type === 'property' && item.key === KEY);
  if (existing) {
    existing.value = VALUE;
  } else {
    properties.push({ type: 'property', key: KEY, value: VALUE });
  }
  return properties;
}

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = setGradleJvmArgs(cfg.modResults);
    return cfg;
  });
};

module.exports.setGradleJvmArgs = setGradleJvmArgs;
module.exports.GRADLE_JVM_ARGS = VALUE;
